precision mediump float;
uniform sampler2D u_texture;
uniform int u_film_stock;
uniform float u_exposure, u_highlights, u_shadows, u_color_grade_intensity, u_grain_amount;
uniform vec2 u_resolution;
uniform float u_time;
varying vec2 v_texCoord;

float random(vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

vec3 applyFilmStock(vec3 color, int stock) {
  if (stock == 0) { // Kodak Vision
    color.r *= 1.05;
    color.g *= 0.98;
    color.b *= 0.95;
  } else if (stock == 1) { // Fuji Eterna
    color.r *= 0.95;
    color.g *= 1.02;
    color.b *= 1.03;
  } else if (stock == 2) { // Agfa X
    color.r *= 1.1;
    color.g *= 0.95;
    color.b *= 0.9;
  } else if (stock == 3) { // Ilford Delta (B&W)
    float gray = dot(color, vec3(0.299, 0.587, 0.114));
    color = vec3(gray);
  }
  return color;
}

void main() {
  vec4 color = texture2D(u_texture, v_texCoord);

  // Exposure adjustment
  color.rgb *= pow(2.0, u_exposure);

  // Highlight/Shadow adjustment
  float luminance = dot(color.rgb, vec3(0.299, 0.587, 0.114));
  if (luminance > 0.7) {
    color.rgb = mix(color.rgb, color.rgb * (1.0 + u_highlights), luminance - 0.7);
  } else if (luminance < 0.3) {
    color.rgb = mix(color.rgb, color.rgb * (1.0 + u_shadows), 0.3 - luminance);
  }

  // Apply film stock characteristics
  vec3 filmColor = applyFilmStock(color.rgb, u_film_stock);
  color.rgb = mix(color.rgb, filmColor, u_color_grade_intensity);

  // Film curve (S-curve)
  color.rgb = color.rgb / (color.rgb + vec3(0.187)) * 1.035;

  // Film grain
  if (u_grain_amount > 0.0) {
    float grain = (random(v_texCoord + u_time) - 0.5) * u_grain_amount * 0.1;
    color.rgb += grain;
  }

  gl_FragColor = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_light_source;
uniform float u_flare_intensity, u_streak_length;
uniform vec3 u_flare_color;
uniform bool u_chromatic_ring;
varying vec2 v_texCoord;

void main() {
  vec4 color = texture2D(u_texture, v_texCoord);

  vec2 center = vec2(0.5, 0.5);
  vec2 lightDir = u_light_source - center;
  vec2 flareDir = center - u_light_source;

  // Distance from light source
  float distToLight = length(v_texCoord - u_light_source);

  // Main flare halo
  float halo = 1.0 / (1.0 + distToLight * 10.0);
  halo = pow(halo, 3.0) * u_flare_intensity;

  // Chromatic rings
  vec3 flareContrib = vec3(0.0);
  if (u_chromatic_ring) {
    float ring1 = abs(distToLight - 0.1);
    float ring2 = abs(distToLight - 0.15);
    float ring3 = abs(distToLight - 0.2);

    flareContrib.r += (1.0 / (1.0 + ring1 * 50.0)) * 0.3;
    flareContrib.g += (1.0 / (1.0 + ring2 * 50.0)) * 0.3;
    flareContrib.b += (1.0 / (1.0 + ring3 * 50.0)) * 0.3;
  }

  // Lens streaks
  if (u_streak_length > 0.0) {
    vec2 streakDir = normalize(lightDir);
    float streakDist = abs(dot(v_texCoord - center, vec2(-streakDir.y, streakDir.x)));
    float streak = (1.0 / (1.0 + streakDist * 100.0)) * u_streak_length;

    float alongStreak = dot(v_texCoord - center, streakDir);
    if (abs(alongStreak) < 0.5) {
      flareContrib += u_flare_color * streak * 0.2;
    }
  }

  // Combine flare effects
  vec3 totalFlare = u_flare_color * halo + flareContrib;
  color.rgb += totalFlare * u_flare_intensity;

  gl_FragColor = vec4(color.rgb, color.a);
}

precision mediump float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_focus_distance, u_focus_range, u_blur_amount;
uniform int u_bokeh_shape;
varying vec2 v_texCoord;

// Simple depth estimation based on luminance and position
float estimateDepth(vec2 coord) {
  vec4 color = texture2D(u_texture, coord);
  float luminance = dot(color.rgb, vec3(0.299, 0.587, 0.114));

  // Use vertical position as simple depth cue (objects lower are closer)
  float depthFromPosition = 1.0 - coord.y;

  // Combine with luminance (brighter objects tend to be closer)
  return mix(depthFromPosition, luminance, 0.3);
}

vec4 bokehBlur(sampler2D tex, vec2 coord, float radius) {
  vec4 color = vec4(0.0);
  float total = 0.0;

  int samples = int(radius * 2.0) + 1;

  for (int x = -10; x <= 10; x++) {
    for (int y = -10; y <= 10; y++) {
      if (x*x + y*y > samples*samples) continue;

      vec2 offset = vec2(float(x), float(y)) / u_resolution * radius;

      // Bokeh shape modification
      float weight = 1.0;
      if (u_bokeh_shape == 1) { // Hexagonal
        float angle = atan(float(y), float(x));
        weight = 0.5 + 0.5 * cos(angle * 6.0);
      } else if (u_bokeh_shape == 2) { // Star
        float angle = atan(float(y), float(x));
        weight = 0.3 + 0.7 * abs(cos(angle * 4.0));
      }

      color += texture2D(tex, coord + offset) * weight;
      total += weight;
    }
  }

  return color / total;
}

void main() {
  float depth = estimateDepth(v_texCoord);

  // Calculate distance from focus plane
  float distanceFromFocus = abs(depth - u_focus_distance);

  // Calculate blur radius
  float blurRadius = 0.0;
  if (distanceFromFocus > u_focus_range) {
    blurRadius = (distanceFromFocus - u_focus_range) * u_blur_amount;
  }

  vec4 color;
  if (blurRadius > 0.5) {
    color = bokehBlur(u_texture, v_texCoord, blurRadius);
  } else {
    color = texture2D(u_texture, v_texCoord);
  }

  gl_FragColor = color;
}
